{
…
   bday [4].name  = "Rich F.";

   bday [5].month = 4;     // Paul
   bday [5].day   = 24;
   bday [5].year  = 1996;
   bday [5].name  = "Paul R.";

   RAP_Bday();

   if ( bday_num != EMPTY )
   {
      printf ("Birthday() = %s\n", bday [ bday_num ].name );
   }

   // ================================================

   if ( access ( RAP_SetupFilename(), 0 ) != 0 )
      EXIT_Error ("You Must run SETUP.EXE First !!");

   if ( ! INI_InitPreference( RAP_SetupFilename() ) )
      EXIT_Error ("SETUP Error");

   fflush ( stdout );
   TSM_Install ( 140 );
   KBD_Install();
   GFX_InitSystem();
   SWD_Install ( FALSE );

   IPT_LoadPrefs();

   switch ( control )
   {
      default:
         printf ("PTR_Init()-Auto\n");
         fflush ( stdout );
         ptrflag = PTR_Init ( P_MOUSE );
         usekb_flag = TRUE;
         break;

      case I_JOYSTICK:
         printf ("PTR_Init()-Joystick\n");
         fflush ( stdout );
         ptrflag = PTR_Init ( P_JOYSTICK );
         usekb_flag = FALSE;
         break;

      case I_MOUSE:
         printf ("PTR_Init()-Mouse\n");
         fflush ( stdout );
         ptrflag = PTR_Init ( P_MOUSE );
         usekb_flag = FALSE;
         break;
   }

   #ifdef REG_VERSION
      printf("Registered EXE!\n");
      fflush ( stdout );
      GLB_InitSystem ( argv[0], 6, NUL );
   #else
      reg_flag = FALSE;
      fflush ( stdout );
      GLB_InitSystem ( argv[0], 2, NUL );
      reg_flag = FALSE;
      gameflag[1] = FALSE;
      gameflag[2] = FALSE;
      gameflag[3] = FALSE;
   #endif

   if ( reg_flag )
   {
      tptr = GLB_GetItem ( ATENTION_TXT );
      printf ( "%s\n", tptr );
      GLB_FreeItem ( ATENTION_TXT );
   }

   SND_InitSound();
   IPT_Init();
   GLB_FreeAll();
   RAP_InitMem();

   if ( !RAP_TestDIZ() )
   {
      if ( !reg_flag )
      {
         fflush ( stdout );
      }
      else
      {
         var1 = GLB_LockItem ( DIZ_ERR );
         printf ( "\n%s\n", var1 );
         fflush ( stdout );
         exit(1);
      }
   }

   printf ("Loading Graphics\n");

   tptr     = GLB_LockItem ( PALETTE_DAT );
   memset ( tptr, 0, 3 );
   palette  = (BYTE *)tptr;
   SHADOW_Init();
   FLAME_Init();

   fflush ( stdout );

   if ( ptrflag )
   {
      cursor_pic = GLB_LockItem ( CURSOR_PIC );
      PTR_SetPic ( cursor_pic );
      PTR_SetPos ( 160, 100 );
      PTR_DrawCursor ( FALSE );
   }

   // = SET UP SHIP PICTURES =========================
   for ( loop = 0; loop < 7; loop++ )
   {
      lship [ loop ] = LPLAYER_PIC + (DWORD)loop;

      if ( GAME2 )
      {
         dship [ loop ]    = DPLAYER_PIC + (DWORD)loop;
         fship [ loop ]    = FPLAYER_PIC + (DWORD)loop;
      }
   }

   // = LOAD IN FLAT LIBS  =========================
   for ( loop = 0; loop < 4; loop++ )
   {
      if ( gameflag [ loop ] )
      {
         item = GLB_GetItemID ( flatnames [ loop ] );
         flatlib [ loop ] = ( FLATS * )GLB_LockItem ( item );
      }
      else
         flatlib[loop] = NUL;
   }

   // = LOAD IN 0-9 $ SPRITE PICS  =========================
   for ( loop = 0; loop < 11; loop++ )
   {
      item = ( N0_PIC + (DWORD)loop );
      numbers[loop] = GLB_LockItem ( item );
   }

   FLAME_InitShades();
   HELP_Init();
   OBJS_Init();
   TILE_Init();
   SHOTS_Init();
   ESHOT_Init();
   BONUS_Init();
   ANIMS_Init();
   SND_Setup();

   GFX_SetPalRange ( 0, ROTPAL_START-1 );
   GFX_InitVideo ( palette );
   SHADOW_MakeShades();

   RAP_ClearPlayer();

   #ifdef TAIWAN_VERSION
      tai_flag = TRUE;
      INTRO_Taiwan();
   #endif

   if ( !godmode )
      INTRO_Credits();

   if ( demo_flag != DEMO_PLAYBACK )
   {
      SND_PlaySong ( RINTRO_MUS, TRUE, TRUE );
      INTRO_PlayMain();
      SND_PlaySong ( MAINMENU_MUS, TRUE, TRUE );
   }
   else if ( demo_flag == DEMO_PLAYBACK )
   {
      DEMO_LoadFile();
      DEMO_Play ();
//      EXIT_Error ("Demo Play done");
   }

   cur_game     = 0;
   game_wave[0] = 0;
   game_wave[1] = 0;
   game_wave[2] = 0;
   game_wave[3] = 0;

   if ( cur_game != 0 )
      printf ( copyright );

   for (;;)
   {
      WIN_MainMenu();
      WIN_MainLoop();
   }

}

