import fs from 'node:fs';

const SEED = 0x19;
const serial = "32768GLB";
const klen = serial.length;
const kidx0 = SEED % klen;

function decrypt(buf){
  const out = Buffer.from(buf);
  let prev = serial.charCodeAt(kidx0);
  let kidx = kidx0;
  for(let i=0;i<out.length;i++){
    const byte = out[i];
    let d = (byte - serial.charCodeAt(kidx) - prev) % 256;
    if (d < 0) d += 256;
    out[i] = d;
    prev = byte;
    kidx = (kidx+1) % klen;
  }
  return out;
}

function parseGlb(path){
  const b = fs.readFileSync(path);
  const head = decrypt(b.subarray(0,28));
  const opt = head.readUInt32LE(0);
  const offset = head.readUInt32LE(4);
  const filesize = head.readUInt32LE(8);
  const name = head.subarray(12,28).toString('latin1').replace(/\0.*$/,'');
  const count = offset; // num items
  console.log(`## ${path}`);
  console.log(`head opt=${opt} numitems=${count} filesize=${filesize} name='${name}'`);
  const idtStart = 28;
  const items = [];
  for(let i=0;i<count;i++){
    const k = decrypt(b.subarray(idtStart + i*28, idtStart + (i+1)*28));
    const iopt = k.readUInt32LE(0);
    const ioff = k.readUInt32LE(4);
    const isize = k.readUInt32LE(8);
    const iname = k.subarray(12,28).toString('latin1').replace(/\0.*$/,'');
    items.push({i, iopt, ioff, isize, iname});
  }
  return items;
}

for (const f of ['FILE0000.GLB','FILE0001.GLB']) {
  const items = parseGlb('data/'+f);
  console.log(`  total ${items.length} items`);
  // print interesting ones
