               case S_TURRET:
                  break;

                default:
                  shot = SHOTS_Remove ( shot );
                  continue;
            }
         }
      }

      if ( !lib->move_flag ) continue;

      if ( lib->use_plot )
      {
         MoveSobj ( &shot->move, shot->speed );
      }
