ENEMY_Get (
VOID
)
{
   SPRITE_SHIP *  sh;

   if ( !free_enemy )
      EXIT_Error ("ENEMY_Get() - Max Sprites");

   numships++;

   sh = free_enemy;
   free_enemy = free_enemy->next;

   memset ( sh, 0 ,sizeof ( SPRITE_SHIP ) );

   sh->next = &last_enemy;
   sh->prev = last_enemy.prev;
   last_enemy.prev = sh;
   sh->prev->next = sh;

