const SEED=0x19; const serial="32768GLB"; const klen=serial.length; const kidx0=SEED%klen;
export function decrypt(buf){
  const out=Buffer.from(buf);
  let prev=serial.charCodeAt(kidx0), kidx=kidx0;
  for(let i=0;i<out.length;i++){
    const byte=out[i];
    let d=(byte - serial.charCodeAt(kidx) - prev) % 256;
    if(d<0) d+=256;
    out[i]=d;
    prev=byte;
    kidx=(kidx+1)%klen;
  }
  return out;
}
const b=fs.readFileSync('data/FILE0001.GLB');
// block-chained decrypt: decrypt contiguous blocks of 10 entries
function idtEntries(){
  const head=decrypt(b.subarray(0,28)); const count=head.readUInt32LE(4);
  const out=[];
  let j=0;
  while(j<count){
    const k=Math.min(10,count-j);
    const blk=decrypt(b.subarray(28+j*28,28+(j+k)*28));
