   cur->smokeflag       = FALSE;
   cur->speed           = 6;
   for ( loop = 0; loop < cur->num_frames; loop++ )
   {
      item = cur->item + (DWORD)loop;
      cur->pic [ loop ] = GLB_LockItem ( item );
   }
   h = ( GFX_PIC * )cur->pic [ 0 ];
   cur->xoff            = h->width>>1;
   cur->yoff            = h->height>>1;

   cur = &plib [ LIB_MISSLE ];
