   cur->num_frames      = 2;
   cur->smokeflag       = TRUE;
   cur->speed           = 10;
   for ( loop = 0; loop < cur->num_frames; loop++ )
   {
      item = cur->item + (DWORD)loop;
      cur->pic [ loop ] = GLB_LockItem ( item );
   }
   h = ( GFX_PIC * )cur->pic [ 0 ];
   cur->xoff            = h->width>>1;
   cur->yoff            = h->height>>1;

   cur = &plib [ LIB_MINES ];
   cur->hits            = 16;
   cur->item            = MINE_BLK;
   cur->num_frames      = 2;
   cur->smokeflag       = FALSE;
   cur->speed           = 0;
   for ( loop = 0; loop < cur->num_frames; loop++ )
   {
      item = cur->item + (DWORD)loop;
      cur->pic [ loop ] = GLB_LockItem ( item );
   }
   h = ( GFX_PIC * )cur->pic [ 0 ];
   cur->xoff            = h->width>>1;
   cur->yoff            = h->height>>1;

   cur = &plib [ LIB_LASER ];
   cur->hits            = 12;
   cur->item            = ELASER_BLK;
   cur->num_frames      = 4;
   cur->smokeflag       = FALSE;
   cur->speed           = 6;
   for ( loop = 0; loop < cur->num_frames; loop++ )
   {
      item = cur->item + (DWORD)loop;
      cur->pic [ loop ] = GLB_LockItem ( item );
   }
   h = ( GFX_PIC * )cur->pic [ 0 ];
   cur->xoff            = h->width>>1;
   cur->yoff            = h->height>>1;

   cur = &plib [ LIB_PLASMA ];
