OBJS_FreePics (
VOID
)
{
   OBJ_LIB * lib;
   INT       loop,i;

   for ( loop = 0; loop < S_LAST_OBJECT; loop++ )
   {
      lib = &obj_lib [ loop ];

      if ( lib && lib->item != EMPTY )
      {
