   OBJ_LIB *   lib   = &obj_lib [ type ];
   INT         rval  = 0;

   if ( !cur )
      return ( 0 );

   plr.score += OBJS_GetResale ( type );

   if ( type == S_DETECT )
   {
      p_objs [ type ] = NUL;
      return ( 0 );
