/***************************************************************************
OBJS_SubEnergy()
 ***************************************************************************/
INT                        // RETURN: return nums in OBJ
OBJS_SubEnergy (
INT      amt               // INPUT : amount to subtract
)
{
   extern BOOL godmode;
   OBJ *  cur;

   if ( godmode ) return ( 0 );

   if ( startendwave != EMPTY )  return ( 0 );

   cur = p_objs [ S_SUPER_SHIELD ];

   if ( curplr_diff == DIFF_0 && amt > 1 )
      amt = amt>>1;

   if ( cur )
   {
      ANIMS_StartAnim ( A_SUPER_SHIELD, 0, 0 );

      SND_Patch ( FX_SHIT, 127 );

      cur->num -= amt;

      if ( cur->num < 0 )
         OBJS_Del ( S_SUPER_SHIELD );
   }
   else
   {
      cur = p_objs [ S_ENERGY ];
      if ( !cur ) return(0);

      SND_Patch ( FX_HIT, 127 );

      cur->num -= amt;

      if ( cur->num < 0 )
         cur->num = 0;
   }

   return ( cur->num );
}

/***************************************************************************
OBJS_AddEnergy()
 ***************************************************************************/
INT                        // RETURN: return nums in OBJ
OBJS_AddEnergy (
INT      amt               // INPUT : amount to add
)
{
   OBJ *  cur;

   cur = p_objs [ S_ENERGY ];
   if ( !cur ) return(0);

   if ( cur->num < cur->lib->max_cnt )
   {
      cur = p_objs [ S_ENERGY ];

      if ( cur->num == 0 )
         return ( 0 );

      cur->num += amt;

      if ( cur->num > cur->lib->max_cnt )
         cur->num = cur->lib->max_cnt;
   }
   else
   {
      cur = p_objs [ S_SUPER_SHIELD ];
      if ( !cur ) return(0);

      if ( cur->num == 0 )
         return ( 0 );

      cur->num += amt>>2;

      if ( cur->num > cur->lib->max_cnt )
         cur->num = cur->lib->max_cnt;
   }

   return ( cur->num );
}

