ANIMS_DisplayGround (
VOID
)
{
   ANIMS    *  cur;
   BYTE     *  pic;

   for ( cur=first_anims.next; cur!=&last_anims; cur=cur->next )
   {
      if ( cur->groundflag != GROUND ) continue;

      pic = GLB_GetItem ( cur->item );

      if ( cur->lib->transparent )
         GFX_ShadeShape ( LIGHT, pic, cur->dx, cur->dy );
      else
