   memset ( &plr, 0, sizeof ( PLAYEROBJ ) );

   plr.sweapon     = EMPTY;
   plr.diff[0]     = DIFF_3;
   plr.diff[1]     = DIFF_3;
   plr.diff[2]     = DIFF_3;
   plr.id_pic      = 0;

   RAP_SetPlayerDiff();

   OBJS_Add ( S_FORWARD_GUNS );
