   OBJS_Add ( S_ENERGY );
   OBJS_Add ( S_ENERGY );
   OBJS_Add ( S_DETECT );
   plr.score = 10000;

   switch ( game )
   {
      default:
         OBJS_Add ( S_MICRO_MISSLE );
         OBJS_Add ( S_MEGA_BOMB );
