/***************************************************************************
DEMO_GLBFile (
 ***************************************************************************/
VOID
DEMO_GLBFile (
DWORD item
)
{
   BYTE * mem;

   mem = GLB_GetItem ( item );
   if ( !mem ) return;

   memcpy ( playback, mem, sizeof ( playback ) );

   cur_play = 1;

   max_play  = playback[0].playerpic;
   demo_game = playback [0].px;
   demo_wave = playback [0].py;

   GLB_FreeItem ( item );
}

/***************************************************************************
