VOID
DEMO_LoadFile (
VOID
)
{
   INT   filesize;

   filesize = GLB_ReadFile ( demo_name, NUL );
   GLB_ReadFile ( demo_name, playback );

   cur_play = 1;

   max_play  = playback[0].playerpic;
   demo_game = playback [0].px;
   demo_wave = playback [0].py;
}

