/***************************************************************************
WIN_MainLoop() - Handles Locker/Register/Store/Hangar and starting game
 ***************************************************************************/
VOID
WIN_MainLoop (
VOID
)
{
   extern   INT              demo_flag;
   INT      rval           = EMPTY;
   BOOL     abort_flag     = FALSE;
   INT      dwrap;
   INT      loop;

   ingameflag = TRUE;

   SND_PlaySong ( HANGAR_MUS, TRUE, TRUE );

   for (;;)
   {
      if ( demo_flag != DEMO_RECORD )
      {
         if ( rval == EMPTY )
         {
            rval = WIN_Hangar();
         }

         switch ( rval )
         {
            case HANG_MISSION:
               rval = EMPTY;
               break;

            default:
               return;

            case HANG_SUPPLIES:
               STORE_Enter();
               hangto = HANGTOMISSION;
               rval = EMPTY;
               continue;
         }
      }

      if  ( !WIN_ShipComp() )
         continue;

      if ( demo_flag == DEMO_RECORD )
         DEMO_MakePlayer( cur_game );

      switch ( cur_game )
      {
         default:
         case 0:
            SND_PlaySong ( songsg1 [ game_wave [ cur_game ] ], TRUE, TRUE );
            break;
         case 1:
            SND_PlaySong ( songsg2 [ game_wave [ cur_game ] ], TRUE, TRUE );
            break;
         case 2:
            SND_PlaySong ( songsg3 [ game_wave [ cur_game ] ], TRUE, TRUE );
            break;
      }

      WIN_LoadComp();
      RAP_LoadMap();
      GFX_SetRetraceFlag ( FALSE );

      abort_flag = Do_Game();

      hangto = HANGTOSTORE;

      GFX_SetRetraceFlag ( TRUE );

      if ( OBJS_GetAmt ( S_ENERGY ) <= 0 )
      {
         ingameflag = FALSE;
         SND_PlaySong ( RAP5_MUS, TRUE, TRUE );
         INTRO_Death();
         return;
      }

      if ( abort_flag )
      {
         INTRO_Landing();
         continue;
      }

      dwrap = diff_wrap [ plr.diff [ cur_game ] ] - 1;

      if ( game_wave [ cur_game ] == dwrap )
      {
         if ( ( plr.diff [ cur_game ] == DIFF_0 ) && !plr.fintrain )
         {
            OBJS_Init();
            plr.sweapon = EMPTY;
            plr.fintrain = TRUE;
            plr.score = 0;
            OBJS_Add ( S_FORWARD_GUNS );
            OBJS_Add ( S_ENERGY );
            OBJS_Add ( S_ENERGY );
            OBJS_Add ( S_ENERGY );
            plr.score = 10000;

            if ( plr.diff [ cur_game ] < DIFF_3 )
               plr.diff [ cur_game ]++;

            for ( loop = 0; loop < 4; loop++ )
            {
               if ( plr.diff [ loop ] == DIFF_0 )
               {
                  plr.diff [ loop ] = DIFF_1;
               }
            }
         }
         else
         {
            if ( plr.diff [ cur_game ] < DIFF_3 )
               plr.diff [ cur_game ]++;
         }

         RAP_SetPlayerDiff();

         game_wave [ cur_game ] = 0;

         if ( dwrap < 8 )
         {
            WIN_WinGame ( 3 );         // SHOW TRAINING COMPLETE STUFF
            cur_game = 0;
            game_wave [0] = 0;
            game_wave [1] = 0;
            game_wave [2] = 0;
         }
         else
         {
            if ( !abort_flag )
            {
               INTRO_EndGame ( cur_game );
               cur_game++;
            }
         }

         if ( cur_game >= 3 )
            cur_game = 0;

         if ( !gameflag [ cur_game ] )
            cur_game = 0;
      }
      else
      {
         if ( !abort_flag )
            game_wave [ cur_game ]++;

         INTRO_Landing();
      }
   }
}

