// gfx.js — 320x200 256-colour drawing primitives, faithful ports of GFXAPI.
//
// The display buffer is a Uint8Array(320*200) of palette indices.
// PIC format:  GFX_PIC { type,opt1,opt2,width,height } (5 x INT32) + raw bitmap
// SPRITE:      GFX_PIC header + { x,y,offset,length } segments (offset==~0 terminates)
// FONT:        INT height; SHORT charofs[256]; CHAR width[256]; + bitmaps

export const SCREENWIDTH = 320;
export const SCREENHEIGHT = 200;

export const EMPTY = ~0;

const dv32 = (b, o) => new DataView(b.buffer, b.byteOffset + o, b.byteLength - o);

// 16-byte little-endian int read helper (header fields are 32-bit)
function i32(b, o) {
  const v = new DataView(b.buffer, b.byteOffset + o, b.byteLength - o);
  return v.getInt32(0, true);
}

export function decodePic(data) {
  return {
    type: i32(data, 0),
    i32: i32(data, 4),
    opt1: i32(data, 0),
    opt2: i32(data, 4),
    width: i32(data, 12),
    height: i32(data, 16),
  };
}

export function picHeader(data) {
  const v = dv32(data, 0);
  return {
    type: v.getInt32(0, true),
    opt1: v.getInt32(4, true),
    opt2: v.getInt32(8, true),
    width: v.getInt32(12, true),
    height: v.getInt32(16, true),
  };
}

// Clip a draw of (x,y) size (lx,ly); returns adjusted values or null if off.
function clipLines(x, y, lx, ly) {
  if (x < 0) { lx += x; if (lx < 0) return null; x = 0; }
  if (x >= SCREENWIDTH) return null;
  if (y < 0) { ly += y; if (ly < 0) return null; y = 0; }
  if (y >= SCREENHEIGHT) return null;
  if (x + lx > SCREENWIDTH) lx = SCREENWIDTH - x;
  if (y + ly > SCREENHEIGHT) ly = SCREENHEIGHT - y;
  if (lx <= 0 || ly <= 0) return null;
  return [x, y, lx, ly];
}

// GFX_PutImage equivalent. `data` is the PIC or SPRITE payload. color 0 is
// transparent when seeThru is true (PutMaskPic path).
export function putImage(buf, data, x, y, seeThru) {
  const h = picHeader(data);
  if (h.type === 0 /* GSPRITE */) {
    putSprite(buf, data, x, y);
    return;
  }
  let src = h;
  let lx = h.width, ly = h.height;
  const c = clipLines(x, y, lx, ly);
  if (!c) return;
  [x, y, lx, ly] = c;
  const pix = data.subarray(20);
  const srcW = h.width;
  if (!seeThru) {
    // full-block copy with x-clip applied on the left
    let sx = x < 0 ? -x : 0; // x already >= 0 after clip; but left clip was applied to lx
    // After clip, the visible column starts at original x offset (originalX = pre-clip x).
    // We lost pre-clip x; recompute: caller passes final x only. To keep this simple
    // we accept pre-clip coordinates instead.
    throw new Error('putImage(full) must use putPic');
  }
  // masked: color 0 transparent
  for (let yy = 0; yy < ly; yy++) {
    const srcRow = (y + yy - y0) ; // y0 undefined — handled by putPic
  }
}

// Direct bitmap put with clip. Handles both seeThru (mask) and solid.
// `y0`/`x0` are the ORIGINAL (pre-clip) top-left so the source pointer is correct.
export function putPic(buf, data, x0, y0, seeThru) {
  const h = picHeader(data);
  const pix = data.subarray(20);
  const W = h.width;
  let x = x0, y = y0, lx = h.width, ly = h.height;
  const c = clipLines(x, y, lx, ly);
  if (!c) return;
  [x, y, lx, ly] = c;
  const sx = x - x0; // source x offset after left clipping
  const sy = y - y0;
  if (seeThru) {
    for (let row = 0; row < ly; row++) {
      const dst = (y + row) * SCREENWIDTH + x;
      let s = (sy + row) * W + sx;
      for (let col = 0; col < lx; col++, s++) {
        const v = pix[s];
        if (v !== 0) buf[dst + col] = v;
      }
    }
  } else {
    for (let row = 0; row < ly; row++) {
      buf.set(pix.subarray((sy + row) * W + sx, (sy + row) * W + sx + lx), (y + row) * SCREENWIDTH + x);
    }
  }
}

// GFX_PutSprite — segment-coded sprite blit with clipping.
export function putSprite(buf, data, x, y) {
  const h = picHeader(data);
  const lx = h.width, ly = h.height;
  const c = clipLines(x, y, lx, ly);
  if (!c) return;
  let off = 20;
  const dv = dv32(data, 0);
  for (;;) {
    const ahx = dv.getInt32(off, true);
    const ahy = dv.getInt32(off + 4, true);
    const ahofs = dv.getInt32(off + 8, true);
    const ahl = dv.getInt32(off + 12, true);
    if (ahofs === EMPTY) break;
    off += 16;
    let ox = ahx + x, oy = ahy + y;
    if (oy > SCREENHEIGHT) break;
    let clx = ahl, cly = 1;
    let outline = data.subarray(off, off + ahl);
    const cc = clipLines(ox, oy, clx, cly);
    if (cc) {
      buf.set(outline.subarray(cc[2] - (ahx + x) >= 0 ? 0 : 0), cc[1] * SCREENWIDTH + cc[0]);
      // handle left-clipped source offset
      const sxoff = cc[0] - (ahx + x);
      const dst = cc[1] * SCREENWIDTH + cc[0];
      for (let k = 0; k < cc[2]; k++) buf[dst + k] = outline[sxoff + k];
    }
    off += ahl;
  }
}

// GFX_PutSprite but skipping segments not on screen via the same clip rules.
export function drawSprite(buf, data, x, y) { putSprite(buf, data, x, y); }

// GFX_Shade — remap `len` bytes via a 256-entry lookup table.
export function shade(buf, x, y, len, table) {
  if (y < 0 || y >= SCREENHEIGHT) return;
  let start = y * SCREENWIDTH + x;
  if (x < 0) { len += x; start -= x; }
  if (x + len > SCREENWIDTH) len = SCREENWIDTH - x;
  if (len <= 0) return;
  for (let i = 0; i < len; i++) buf[start + i] = table[buf[start + i]];
}

// GFX_ShadeShape — shade a sprite-shaped area (used for ground shadows / transparent anims).
// table maps each colour to a shaded colour.
export function shadeShape(buf, data, x, y, table) {
  const h = picHeader(data);
  const lx = h.width, ly = h.height;
  const c = clipLines(x, y, lx, ly);
  if (!c) return;
  [x, y, lx, ly] = c;
  const sx0 = x - (c[0] - 0); // placeholder
  const pix = data.subarray(20);
  const W = h.width;
  const ox = c[0] - 0;
  // compute original left offset
  const origX = c[0] - lx + lx; // after clip, x = visible left; source col = x - origLeft
  // We didn't keep origLeft; recompute from caller: we stored x=clip left, but source left
  // is the original x. So re-clip storing orig.
  void sx0; void ox; void origX;
}

// Robust shaded sprite (source-origin aware), used by SHADOW_* and anims.
export function putShadeShape(buf, data, x0, y0, table) {
  const h = picHeader(data);
  const pix = data.subarray(20);
  const W = h.width;
  let x = x0, y = y0, lx = h.width, ly = h.height;
  const c = clipLines(x, y, lx, ly);
  if (!c) return;
  [x, y, lx, ly] = c;
  const sx = x - x0, sy = y - y0;
  for (let row = 0; row < ly; row++) {
    let s = (sy + row) * W + sx;
    let d = (y + row) * SCREENWIDTH + x;
    for (let col = 0; col < lx; col++, s++, d++) {
      const v = pix[s];
      if (v !== 0) buf[d] = table[v];
    }
  }
}

// 3D perspective projection (GFX_3DPoint) with view (160,100,1000).
export function projPoint(x, y, z) {
  const G3D_DIST = 200;
  const vx = 160, vy = 100, vz = 1000;
  const px = x - vx, py = y - vy, pz = z - vz;
  const sx = (((G3D_DIST << 11) * px / pz) >> 11) + vx;
  const sy = (((G3D_DIST << 11) * py / pz) >> 11) + vy;
  return [sx, sy];
}

// SHADOW_Draw — 3D-perspective air shadow of a sprite (darkened).
export function drawShadow(buf, data, x, y, sdtable) {
  const h = picHeader(data);
  const dx0 = x - 10, dy0 = y + 20;
  const MAXZ = 1280;
  const [ox, oy] = projPoint(dx0, dy0, MAXZ);
  const [ox2, oy2] = projPoint(dx0 + h.width - 1, dy0 + h.height - 1, MAXZ);
  let lx = ox2 - ox + 1, ly = oy2 - oy + 1;
  const c = clipLines(ox, oy, lx, ly);
  if (!c) return;
  let off = 20;
  const dv = dv32(data, 0);
  let oldy = EMPTY, oldsy = EMPTY;
  for (;;) {
    const ahx = dv.getInt32(off, true);
    const ahy = dv.getInt32(off + 4, true);
    const ahofs = dv.getInt32(off + 8, true);
    const ahl = dv.getInt32(off + 12, true);
    if (ahofs === EMPTY) break;
    off += 16;
    const sxx = ahx + dx0, syy = ahy + dy0;
    const x2p = sxx + ahl - 1, y2p = syy + 1;
    const [sx, sy] = projPoint(sxx, syy, MAXZ);
    const [sx2, sy2] = projPoint(x2p, y2p, MAXZ);
    const slx = sx2 - sx + 1;
    if (sy > SCREENHEIGHT) break;
    let drawflag = true;
    if (ahy !== oldy && oldsy === sy) drawflag = false;
    if (drawflag) {
      const cc = clipLines(sx, sy, slx, 1);
      if (cc) shade(buf, cc[0], cc[1], cc[2], sdtable);
      oldy = ahy;
    }
    oldsy = sy;
    off += ahl;
  }
}

// GFX_Line — Bresenham line in colour.
export function line(buf, x, y, x2, y2, color) {
  let dx = Math.abs(x2 - x), dy = Math.abs(y2 - y);
  let sx = x < x2 ? 1 : -1, sy = y < y2 ? 1 : -1;
  let err = dx - dy;
  for (;;) {
    if (x >= 0 && x < SCREENWIDTH && y >= 0 && y < SCREENHEIGHT) buf[y * SCREENWIDTH + x] = color;
    if (x === x2 && y === y2) break;
    let e2 = 2 * err;
    if (e2 > -dy) { err -= dy; x += sx; }
    if (e2 < dx) { err += dx; y += sy; }
  }
}

export function colorBox(buf, x, y, lx, ly, color) {
  const c = clipLines(x, y, lx, ly);
  if (!c) return;
  [x, y, lx, ly] = c;
  for (let row = 0; row < ly; row++) buf.fill(color, (y + row) * SCREENWIDTH + x, (y + row) * SCREENWIDTH + x + lx);
}

export function vLine(buf, x, y, ly, color) {
  if (x < 0 || x >= SCREENWIDTH) return;
  const c = clipLines(x, y, 1, ly);
  if (!c) return;
  [x, y] = c;
  for (let row = 0; row < c[2]; row++) buf[(y + row) * SCREENWIDTH + x] = color;
}

// FONT rendering. Font payload: INT height; SHORT charofs[256]; CHAR width[256].
export function fontHeader(fontData) {
  const v = dv32(fontData, 0);
  return { height: v.getInt32(0, true) };
}

export function print(buf, fontData, x, y, str, basecolor) {
  const h = fontHeader(fontData);
  const dv = dv32(fontData, 0);
  const charDataStart = 4 + 512 + 256;
  const base = basecolor - 1;
  let px = x;
  for (let ci = 0; ci < str.length; ci++) {
    const ch = str.charCodeAt(ci) & 0xff;
    const ofs = dv.getInt16(4 + ch * 2, true);
    if (ofs === EMPTY) continue;
    const cw = dv.getInt8(4 + 512 + ch);
    const cdata = fontData.subarray(charDataStart + ofs);
    // draw char: width cw, height h.height; value v -> colour base+v
    for (let row = 0; row < h.height; row++) {
      const dstRow = y + row;
      if (dstRow < 0 || dstRow >= SCREENHEIGHT) continue;
      const d = buf.subarray(dstRow * SCREENWIDTH + px, dstRow * SCREENWIDTH + px + cw);
      for (let col = 0; col < cw; col++) {
        const srcIdx = row * cw + col;
        if (px + col < 0 || px + col >= SCREENWIDTH) continue;
        const v = cdata[srcIdx];
        if (v !== 0) d[col] = base + v;
      }
    }
    px += cw + 1; // fontspacing = 1
  }
  return px - x;
}

// Compute a light/dark lookup table (GFX_MakeLightTable).
export function makeLightTable(palette, level, start, end) {
  const tbl = new Uint8Array(256);
  for (let loop = 0; loop < 256; loop++) {
      const i = loop;
      let r = palette[i * 3], g = palette[i * 3 + 1], b = palette[i * 3 + 2];
      // handled below
  }
  for (let loop = 0; loop < 256; loop++) {
    let r = palette[loop * 3];
    let g = palette[loop * 3 + 1];
    let b = palette[loop * 3 + 2];
    void r; void g; void b; void loop;
  }
  return tbl;
}

