  // We didn't keep origLeft; recompute from caller: we stored x=clip left, but source left
  // is the original x. So re-clip storing orig.
  void sx0; void ox; void origX;
}

// Robust shaded sprite (source-origin aware), used by SHADOW_* and anims.
export function putShadeShape(buf, data, x0, y0, table) {
  const h = picHeader(data);
  const pix = data.subarray(20);
  const W = h.width;
  let x = x0, y = y0, lx = h.width, ly = h.height;
  const c = clipLines(x, y, lx, ly);
  if (!c) return;
  [x, y, lx, ly] = c;
  const sx = x - x0, sy = y - y0;
  for (let row = 0; row < ly; row++) {
    let s = (sy + row) * W + sx;
    let d = (y + row) * SCREENWIDTH + x;
    for (let col = 0; col < lx; col++, s++, d++) {
      const v = pix[s];
      if (v !== 0) buf[d] = table[v];
    }
  }
