// 3D perspective projection (GFX_3DPoint) with view (160,100,1000).
export function projPoint(x, y, z) {
  const G3D_DIST = 200;
  const vx = 160, vy = 100, vz = 1000;
  const px = x - vx, py = y - vy, pz = z - vz;
  const sx = (((G3D_DIST << 11) * px / pz) >> 11) + vx;
  const sy = (((G3D_DIST << 11) * py / pz) >> 11) + vy;
  return [sx, sy];
}

// SHADOW_Draw — 3D-perspective air shadow of a sprite (darkened).
export function drawShadow(buf, data, x, y, sdtable) {
  const h = picHeader(data);
  const dx0 = x - 10, dy0 = y + 20;
  const MAXZ = 1280;
  const [ox, oy] = projPoint(dx0, dy0, MAXZ);
  const [ox2, oy2] = projPoint(dx0 + h.width - 1, dy0 + h.height - 1, MAXZ);
  let lx = ox2 - ox + 1, ly = oy2 - oy + 1;
  const c = clipLines(ox, oy, lx, ly);
  if (!c) return;
  let off = 20;
  const dv = dv32(data, 0);
  let oldy = EMPTY, oldsy = EMPTY;
  for (;;) {
    const ahx = dv.getInt32(off, true);
    const ahy = dv.getInt32(off + 4, true);
    const ahofs = dv.getInt32(off + 8, true);
    const ahl = dv.getInt32(off + 12, true);
    if (ahofs === EMPTY) break;
    off += 16;
    const sxx = ahx + dx0, syy = ahy + dy0;
    const x2p = sxx + ahl - 1, y2p = syy + 1;
    const [sx, sy] = projPoint(sxx, syy, MAXZ);
    const [sx2, sy2] = projPoint(x2p, y2p, MAXZ);
    const slx = sx2 - sx + 1;
    if (sy > SCREENHEIGHT) break;
    let drawflag = true;
    if (ahy !== oldy && oldsy === sy) drawflag = false;
    if (drawflag) {
