}

export function colorBox(buf, x, y, lx, ly, color) {
  const c = clipLines(x, y, lx, ly);
  if (!c) return;
  [x, y, lx, ly] = c;
  for (let row = 0; row < ly; row++) buf.fill(color, (y + row) * SCREENWIDTH + x, (y + row) * SCREENWIDTH + x + lx);
}

export function vLine(buf, x, y, ly, color) {
  if (x < 0 || x >= SCREENWIDTH) return;
  const c = clipLines(x, y, 1, ly);
  if (!c) return;
  [x, y] = c;
  for (let row = 0; row < c[2]; row++) buf[(y + row) * SCREENWIDTH + x] = color;
