    const cc = clip(ox, oy, ahl, 1);
    if (cc) {
      const srcOff = cc[0] - ox;
      buf.set(data.subarray(off + srcOff, off + srcOff + cc[2]), cc[1] * SCREENWIDTH + cc[0]);
    }
    off += ahl;
  }
}

// GFX_Shade — remap `len` bytes at (x,y) via a 256-entry table.
export function shade(buf, x, y, len, table) {
  const c = clip(x, y, len, 1);
  if (!c) return;
  for (let i = 0; i < c[2]; i++) buf[c[1] * SCREENWIDTH + c[0] + i] = table[buf[c[1] * SCREENWIDTH + c[0] + i]];
}

// GFX_ShadeShape — shade a sprite-shaped area (ground shadow / transparent anims).
export function putShadeShape(buf, data, x, y, table) {
  const h = picHeader(data);
  let cx = x, cy = y, lx = h.width, ly = h.height;
  const c = clip(cx, cy, lx, ly);
  if (!c) return;
  [cx, cy, lx, ly] = c;
  const sx = cx - x, sy = cy - y;
  const pix = data.subarray(20);
  for (let row = 0; row < ly; row++) {
    let s = (sy + row) * h.width + sx;
    let d = (cy + row) * SCREENWIDTH + cx;
    for (let col = 0; col < lx; col++, s++, d++) {
      const v = pix[s];
      if (v !== 0) buf[d] = table[v];
    }
  }
}

// 3D perspective projection (GFX_3DPoint) with view (160,100,1000).
const G3D_DIST = 200, VIEWX = 160, VIEWY = 100, VIEWZ = 1000;
export function projPoint(x, y, z) {
  const px = x - VIEWX, py = y - VIEWY, pz = z - VIEWZ;
  const sx = (((G3D_DIST << 11) * px / pz) >> 11) + VIEWX;
  const sy = (((G3D_DIST << 11) * py / pz) >> 11) + VIEWY;
  return [sx, sy];
}

// SHADOW_Draw — 3D-perspective air shadow of a sprite (darkened via sdtable).
export function drawShadow(buf, data, x, y, sdtable) {
  const h = picHeader(data);
  const dx0 = x - 10, dy0 = y + 20;
  const MAXZ = 1280;
  const [ox, oy] = projPoint(dx0, dy0, MAXZ);
  const [ox2, oy2] = projPoint(dx0 + h.width - 1, dy0 + h.height - 1, MAXZ);
  let lx = ox2 - ox + 1, ly = oy2 - oy + 1;
  const c = clip(ox, oy, lx, ly);
  if (!c) return;
  const dv = new DataView(data.buffer, data.byteOffset, data.byteLength);
  let off = 20;
  let oldy = EMPTY, oldsy = EMPTY;
  for (;;) {
    const ahx = dv.getInt32(off, true);
    const ahy = dv.getInt32(off + 4, true);
    const ahofs = dv.getInt32(off + 8, true);
    const ahl = dv.getInt32(off + 12, true);
    if (ahofs === EMPTY) break;
    off += 16;
    const [sx, sy] = projPoint(ahx + dx0, ahy + dy0, MAXZ);
    const [sx2] = projPoint(ahx + dx0 + ahl - 1, ahy + dy0 + 1, MAXZ);
    const slx = sx2 - sx + 1;
    if (sy > SCREENHEIGHT) break;
    let drawflag = true;
    if (ahy !== oldy && oldsy === sy) drawflag = false;
    if (drawflag) {
      const cc = clip(sx, sy, slx, 1);
      if (cc) {
        for (let i = 0; i < cc[2]; i++) {
          const d = cc[1] * SCREENWIDTH + cc[0] + i;
          buf[d] = sdtable[buf[d]];
        }
      }
      oldy = ahy;
    }
    oldsy = sy;
    off += ahl;
  }
}

// GFX_Line — Bresenham line in colour.
export function line(buf, x, y, x2, y2, color) {
  let dx = Math.abs(x2 - x), dy = Math.abs(y2 - y);
  let sx = x < x2 ? 1 : -1, sy = y < y2 ? 1 : -1;
  let err = dx - dy;
  for (;;) {
    if (x >= 0 && x < SCREENWIDTH && y >= 0 && y < SCREENHEIGHT) buf[y * SCREENWIDTH + x] = color;
    if (x === x2 && y === y2) break;
    const e2 = 2 * err;
    if (e2 > -dy) { err -= dy; x += sx; }
    if (e2 < dx) { err += dx; y += sy; }
  }
}

export function colorBox(buf, x, y, lx, ly, color) {
  const c = clip(x, y, lx, ly);
  if (!c) return;
  for (let row = 0; row < c[2]; row++) buf.fill(color, (c[1] + row) * SCREENWIDTH + c[0], (c[1] + row) * SCREENWIDTH + c[0] + c[2]);
}

export function vLine(buf, x, y, ly, color) {
  const c = clip(x, y, 1, ly);
  if (!c) return;
  for (let row = 0; row < c[2]; row++) buf[(c[1] + row) * SCREENWIDTH + x] = color;
}

// FONT rendering. Font payload: INT height; SHORT charofs[256]; CHAR width[256]; data.
export function print(buf, fontData, x, y, str, basecolor) {
  const v = new DataView(fontData.buffer, fontData.byteOffset, fontData.byteLength);
  const height = v.getInt32(0, true);
  const dataStart = 4 + 512 + 256;
  const base = basecolor - 1;
  let px = x;
  for (let ci = 0; ci < str.length; ci++) {
    const ch = str.charCodeAt(ci) & 0xff;
    const ofs = v.getInt16(4 + ch * 2, true);
    if (ofs === EMPTY) continue;
    const cw = v.getInt8(4 + 512 + ch);
    for (let row = 0; row < height; row++) {
      const dy = y + row;
      if (dy < 0 || dy >= SCREENHEIGHT) continue;
      const cdata = fontData.subarray(dataStart + ofs + row * cw, dataStart + ofs + (row + 1) * cw);
      for (let col = 0; col < cw; col++) {
        const dx = px + col;
        if (dx < 0 || dx >= SCREENWIDTH) continue;
        const vc = cdata[col];
        if (vc !== 0) buf[dy * SCREENWIDTH + dx] = base + vc;
      }
    }
    px += cw + 1; // fontspacing = 1
  }
  return px - x;
}

// GFX_MakeLightTable — build a 256-entry remap table that lightens/darkens by `level`.
export function makeLightTable(palette, level, start, end) {
  const tbl = new Uint8Array(256);
  for (let loop = 0; loop < 256; loop++) {
    let r = palette[loop * 3];
    let g = palette[loop * 3 + 1];
    let b = palette[loop * 3 + 2];
    r += level; g += level; b += level;
    if (r < 0) r = 0; else if (r > 63) r = 63;
    if (g < 0) g = 0; else if (g > 63) g = 63;
    if (b < 0) b = 0; else if (b > 63) b = 63;
    // closest colour in [start,end]
    let best = 0, bestDiff = 256 * 3 + 1;
    for (let e = start; e <= end; e++) {
      const diff = Math.abs(palette[e * 3] - r) + Math.abs(palette[e * 3 + 1] - g) + Math.abs(palette[e * 3 + 2] - b);
      if (diff <= bestDiff) { bestDiff = diff; best = e; }
    }
    tbl[loop] = best;
  }
  return tbl;
}
