enemyAdd(sprite) {
  const curlib = this.spriteLib[sprite.slib];
  if (!curlib || !curlib.iname) return;
  const pic = this.getItem(curlib.item);
  const h = this.picHeader(pic);
  const e = {
    lib: curlib,
    item: curlib.item,
    width: h.width, height: h.height, hlx: h.width >> 1, hly: h.height >> 1,
    kami: KAMI_FLY, hits: curlib.hits, edir: E_FORWARD,
    move: null, doneflag: false,
    frame_rate: curlib.frame_rate, speed: curlib.movespeed,
    shoot_disable: false, shoot_on: false, shootagain: NORM_SHOOT,
    shootcount: curlib.shootcnt, shootflag: curlib.shootstart,
    anim_on: false, num_frames: curlib.num_frames, curframe: 0,
    groundflag: false, movepos: 0, multi: 2, eframe: 0, sx: 0, sy: 0,
    x2: 0, y2: 0,
  };
  const tiley = Math.floor(this.tilePos / MAP_COLS) - 3;
  e.y = this.tileYoff - ((tiley - sprite.y) * 32) - 97;
  e.x = (sprite.x * 32) + MAP_LEFT;
  e.x += 16; e.y += 16;
  e.x -= e.hlx; e.y -= e.hly;
  e.x2 = e.x + e.width; e.y2 = e.y + e.height;
  e.move = { x: e.x, y: e.y, x2: 0, y2: 0, delx: 0, dely: 0, addx: 1, addy: 1, err: 0, maxloop: 0, done: false };
  e.sx = e.x; e.sy = e.y;
  e.countdown = curlib.countdown + -e.y;
  e.shootagain = NORM_SHOOT;

