arguments.command:
cat > /tmp/probe.mjs <<'EOF'
import { loadGLB } from 'file:///D:/dev/ab-tasks/raptor-dsv4/js/glb.js';
const glb1 = await loadGLB('file:///D:/dev/ab-tasks/raptor-dsv4/data/FILE0001.GLB');
const raw = glb1.raw('SPRITE1_ITM');
const SIZE=528;
const get = (i,o) => new DataView(raw.buffer, raw.byteOffset+raw.byteOffset, raw.byteLength).getInt32(i*SIZE+o, true);
// Wait: raw.buffer may be offset. Use raw directly with DataView
function dv(o){ return new DataView(raw.buffer, raw.byteOffset+o, raw.byteLength-o); }
function i32(i,o){ return dv(0).getInt32(i*SIZE+o, true); }
function i16(i,o){ return dv(0).getInt16(i*SIZE+o, true); }
// item should be 312 for TARGT1G1 (entry0), 313 for TARGT2G1 (entry1)
for(let o=0;o<40;o+=4){ if(i32(0,o)===312) console.log('item offset =',o); }
// find num_frames (TARGT entries have num_frames 4) — search known offsets
for(let o=40;o<120;o+=4){ if(i32(0,o)===4 && i32(1,o)===4) console.log('candidate num_frames at',o); }
// print a window to infer: dump ints from 16..120 for entry 0
console.log('entry0 ints 16..120:', (()=>{let a=[];for(let o=16;o<=120;o+=4)a.push(`${o}:${i32(0,o)}`);return a.join(' ');})());
console.log('entry1 ints 16..120:', (()=>{let a=[];for(let o=16;o<=120;o+=4)a.push(`${o}:${i32(0,o)}`);return a.join(' ');})());
EOF
node /tmp/probe.mjs

