// simple dodge: move horizontally away from nearest eshot/enemy x
function nearX(){
  let danger = null, dmin = 1e9;
  for (const s of g.eshots) { const dx=Math.abs(s.x-g.player_cx); if(dx<dmin){dmin=dx; danger=s.x;} }
  for (const e of g.enemies) { const dx=Math.abs(e.x+e.hlx-g.player_cx); if(dx<dmin){dmin=dx; danger=e.x+e.hlx;} }
  return danger;
}
let minE=100, endFrame=-1;
for(let f=0; f<6000; f++){
  g.keys.left=false; g.keys.right=false;
  if (f%200<100) { g.keys.left = true; g.keys.right = false; } else { g.keys.left=false; g.keys.right=true; }
  g.frame();
  minE=Math.min(minE,g.energy);
  if(g.end_wave){ endFrame=f; break; }
}
console.log('endFrame', endFrame, 'minEnergy', minE, 'final energy', g.energy, 'score', g.score, 'wave', g.wave);
EOF
