      if(dx<40 && dy<80) sc-=200;
      if(dx<20 && dy<40) sc-=500;
    }
    for(const e of g.enemies){ const ex=e.x+e.hlx; if(Math.abs(ex-tx)<40 && e.y+e.hly>40 && e.y<120) sc-=300; }
