  g.keys.down = g.playery < 60;
  g.frame();
  minE=Math.min(minE,g.energy);
  maxE=Math.max(maxE,g.shots.length);
  if(g.end_wave){ endFrame=f; break; }
}
console.log('endFrame', endFrame, 'minEnergy', minE, 'score', g.score);
