cat > /tmp/test_win.mjs <<'EOF'
import { loadGLB } from 'file:///D:/dev/ab-tasks/raptor-dsv4/js/glb.js';
import { Raptor } from 'file:///D:/dev/ab-tasks/raptor-dsv4/js/engine.js';
const glb0 = await loadGLB('file:///D:/dev/ab-tasks/raptor-dsv4/data/FILE0000.GLB');
const glb1 = await loadGLB('file:///D:/dev/ab-tasks/raptor-dsv4/data/FILE0001.GLB');
const g = new Raptor(glb0, glb1);
g.setAudio({play:()=>false});
g.init();
g.startWave(0);
g.keys.fire=true;
let minE=100, endFrame=-1;
for(let f=0; f<40000; f++){
  // target: nearest enemy above player that's descending; also dodge incoming
  let target=null, best=1e9;
  for(const e of g.enemies){
    if(e.y<200){
      const d = Math.abs(e.x+e.hlx-g.playerx-16) + Math.max(0,e.y-g.playery)*0.5;
      if(d<best){best=d; target=e;}
    }
  }
  let desiredX = 160;
  if(target){ desiredX = target.x+target.hlx; }
  // dodge ships that are about to hit
  for(const e of g.enemies){
    if(e.y+e.hly>g.playery-10 && e.y<g.playery+40 && Math.abs(e.x+e.hlx-(g.playerx+16))<50){
      desiredX = (e.x+e.hlx) < (g.playerx+16) ? 40 : 280; // flee to a side
    }
  }
  // dodge eshots
  for(const s of g.eshots){
    if(s.y>g.playery-60 && s.y<g.playery+10 && Math.abs(s.x-(g.playerx+16))<24) desiredX = s.x<g.playerx+16?280:40;
  }
  g.keys.left = g.playerx+16>desiredX+3; g.keys.right = g.playerx+16<desiredX-3;
  g.keys.up = g.playery>40; g.keys.down = g.playery<40;
  g.frame();
  minE=Math.min(minE,g.energy);
  if(g.end_wave){ endFrame=f; break; }
}
console.log('endFrame', endFrame, 'minE', minE, 'finalE', g.energy, 'score', g.score);
EOF
