const glb0 = await loadGLB('file:///D:/dev/ab-tasks/raptor-dsv4/data/FILE0000.GLB');
const glb1 = await loadGLB('file:///D:/dev/ab-tasks/raptor-dsv4/data/FILE0001.GLB');
const g = new Raptor(glb0, glb1);
g.setAudio({play:()=>false});
g.init();
g.startWave(0);
g.keys.fire=true;
let minE=100, endFrame=-1;
// Strong bot: sweep back and forth fast, staying at y~70, firing constantly.
// Kills what's above while sweeping. Dodge = the sweep itself.
for(let f=0; f<60000; f++){
  const half = 2400; const t = f % (2*half);
  const dir = t < half ? 1 : -1;
  g.keys.left = dir<0; g.keys.right = dir>0;
  g.keys.up = g.playery>70; g.keys.down = g.playery<70;
  // emergency dodge: if an eshot or enemy is directly closing, break pattern
  for(const s of g.eshots){
    if(s.y>g.playery-50 && s.y<g.playery+5 && Math.abs(s.x-(g.playerx+16))<26){
      if(s.x < g.playerx+16){ g.keys.left=false; g.keys.right=true; }
      else { g.keys.left=true; g.keys.right=false; }
    }
  }
  g.frame();
  minE=Math.min(minE,g.energy);
  if(g.end_wave){ endFrame=f; break; }
}
console.log('endFrame', endFrame, 'minE', minE, 'finalE', g.energy, 'score', g.score, 'ships', g.enemies.length);
