         speed--;
         cur->maxloop--;

         if ( cur->maxloop == 0 )
         {
            cur->done = TRUE;
            return ( speed );
         }

         cur->x += cur->addx;
         cur->err += cur->dely;
  
         if ( cur->err > 0 )
         {
            cur->y += cur->addy;
            cur->err -= cur->delx;
         }
      }
   }
   else
   {
      while ( speed )
      {
         speed--;
         cur->maxloop--;

         if ( cur->maxloop == 0 )
         {
            cur->done = TRUE;
            return ( speed );
         }

         cur->y += cur->addy;
         cur->err += cur->delx;
  
         if ( cur->err > 0 )
         {
            cur->x += cur->addx;
            cur->err -= cur->dely;
