/*-------------------------------------------------------------------------*
ENEMY_Get() - Gets An Free Enemy from link list
 *-------------------------------------------------------------------------*/
PRIVATE SPRITE_SHIP *
ENEMY_Get (
VOID
)
{
   SPRITE_SHIP *  sh;

   if ( !free_enemy )
      EXIT_Error ("ENEMY_Get() - Max Sprites");

   numships++;

   sh = free_enemy;
   free_enemy = free_enemy->next;

   memset ( sh, 0 ,sizeof ( SPRITE_SHIP ) );

   sh->next = &last_enemy;
   sh->prev = last_enemy.prev;
   last_enemy.prev = sh;
   sh->prev->next = sh;

   return ( sh );
}

/*-------------------------------------------------------------------------*
ENEMY_Remove () - Removes an Enemy OBJECT from linklist
 *-------------------------------------------------------------------------*/
PRIVATE SPRITE_SHIP *
ENEMY_Remove (
SPRITE_SHIP * sh
)
{
   SPRITE_SHIP * next;

   if ( sh->lib->bossflag )
      numboss--;

   numships--;

   if ( end_waveflag && numships < 1 )
      startendwave = END_DURATION;

   next = sh->prev;

   sh->next->prev = sh->prev;
   sh->prev->next = sh->next;
   
   memset ( sh, 0, sizeof ( SPRITE_SHIP ) );
   sh->item = ~0;

   sh->next = free_enemy;

   free_enemy = sh;

   return ( next );
}

