cat > /tmp/test_evade.mjs <<'EOF'
import { loadGLB } from 'file:///D:/dev/ab-tasks/raptor-dsv4/js/glb.js';
import { Raptor } from 'file:///D:/dev/ab-tasks/raptor-dsv4/js/engine.js';
const glb0 = await loadGLB('file:///D:/dev/ab-tasks/raptor-dsv4/data/FILE0000.GLB');
const glb1 = await loadGLB('file:///D:/dev/ab-tasks/raptor-dsv4/data/FILE0001.GLB');
const g = new Raptor(glb0, glb1);
g.setAudio({play:()=>false});
g.init(); g.startWave(0);
g.keys.fire=true;
let minE=100, endFrame=-1;
for(let f=0; f<120000; f++){
  // evaluate danger at candidate ship positions (center-based)
  function dangerAt(cx, cy){
    let d=0;
    for(const s of g.eshots){
      const dx=Math.abs(s.x-cx), dy=Math.abs(s.y-cy);
      if(dx<16&&dy<16) d+=100;
      const t = (dy>0? (dy<80? 1.0 : 0.2) : 0);
      if(dx<30&&dy<70) d += 20;
    }
    for(const e of g.enemies){
      if(e.groundflag) continue;
      const ex=(e.x+e.x2)/2, ey=(e.y+e.y2)/2;
      const dx=Math.abs(ex-cx), dy=Math.abs(ey-cy);
      if(dx<30&&dy<30) d+=30;
      if(dx<60&&dy<120&&e.y2>cy-10&&e.y<cy+40) d+=8;
    }
    return d;
  }
  // pick best target among grid cells reachable
  let best=null, bestD=1e9;
  for(let gx=0; gx<=304; gx+=16){
    for(let gy=0; gy<=184; gy+=16){
      const d = dangerAt(g.playerx+16, g.playery+16) * 0.5 + 0.01*Math.abs(gx-(g.playerx+16)) + 0.01*Math.abs(gy-(g.playery+16));
      // only consider cells near current
      if(Math.abs(gx-(g.playerx+16))>16||Math.abs(gy-(g.playery+16))>16) continue;
      if(d<bestD){bestD=d;best=[gx,gy];}
    }
  }
  let tx=(best?best[0]:g.playerx+16), ty=(best?best[1]:g.playery+16);
  g.keys.left = g.playerx+16>tx+2; g.keys.right = g.playerx+16<tx-2;
  g.keys.up = g.playery+16>ty+2; g.keys.down = g.playery+16<ty-2;
  g.frame();
  minE=Math.min(minE,g.energy);
  if(g.end_wave){ endFrame=f; break; }
}
console.log('endFrame', endFrame, 'minE', minE, 'finalE', g.energy, 'score', g.score, 'ships', g.enemies.length);
EOF
