import { loadGLB } from 'file:///D:/dev/ab-tasks/raptor-dsv4/js/glb.js';
import { Raptor } from 'file:///D:/dev/ab-tasks/raptor-dsv4/js/engine.js';
const glb0 = await loadGLB('file:///D:/dev/ab-tasks/raptor-dsv4/data/FILE0000.GLB');
const glb1 = await loadGLB('file:///D:/dev/ab-tasks/raptor-dsv4/data/FILE0001.GLB');
const g = new Raptor(glb0, glb1);
g.setAudio({play:()=>false});
g.init(); g.startWave(0);
g.energy = 1000000;
g.keys.fire=false;
g.keys.up=true; g.keys.down=false; g.keys.left=false; g.keys.right=false;
const births={};
const oAdd=g.enemyAdd.bind(g);
g.enemyAdd=function(c){ const e=oAdd(c); births[e]=g.frameNo; return e; };
// find the enemies array index of a given object after add
g.enemyAdd=function(c){
  const before=g.enemies.length;
  const r=oAdd(c);
  // record birth for the newly added (last) enemy
  births[g.enemies[g.enemies.length-1]]=g.frameNo;
  return r;
};
let deaths=[];
const oRem=(idx)=>{};
let endFrame=-1, maxAlive=0;
for(let f=0; f<60000; f++){
  const aliveBefore = new Set(g.enemies);
  g.frame();
  maxAlive=Math.max(maxAlive,g.enemies.length);
  // detect removed enemies
  for(const e of aliveBefore){ if(!g.enemies.includes(e)){ deaths.push({spawn:births[e], death:f, dur:f-births[e]}); } }
  if(g.end_wave){ endFrame=f; break; }
}
deaths.sort((a,b)=>a.spawn-b.spawn);
console.log('endFrame', endFrame, 'maxAlive', maxAlive, 'deaths', deaths.length);
// distribution of durations
const dist={};
for(const d of deaths){ const b=Math.floor(d.dur/200)*200; dist[b]=(dist[b]||0)+1; }
console.log('dur buckets', JSON.stringify(dist));
// last 10 spawns
console.log('last spawns', deaths.slice(-10).map(d=>d.spawn+':'+d.dur).join(', '));
EOF
