const g = new Raptor(glb0, glb1);
g.setAudio({play:()=>false});
g.init(); g.startWave(0);
g.keys.fire=true;
let minE=100, endFrame=-1;
for(let f=0; f<120000; f++){
  // chase: move to be under nearest enemy (x aligned) but avoid eshots/dives
  let tx=160, ty=60;
  let target=null, best=1e9;
  for(const e of g.enemies){
    const d=Math.abs(e.x+e.hlx-(g.playerx+16))+Math.max(0,(e.y+e.hly-g.playery))*0.3;
    if(d<best){best=d; target=e;}
  }
  if(target){ tx=target.x+target.hlx; ty=Math.min(Math.max(target.y+target.hly-16,20),140); }
  // dodge incoming eshots
  for(const s of g.eshots){
    if(s.y>g.playery-70 && s.y<g.playery+5 && Math.abs(s.x-(g.playerx+16))<24){
      if(s.x < g.playerx+16){ tx=280; } else { tx=40; }
    }
  }
  // dodge diving enemies about to hit
  for(const e of g.enemies){
    if(e.y+e.hly>g.playery-6 && e.y<g.playery+40 && Math.abs(e.x+e.hlx-(g.playerx+16))<48){
      tx = (e.x+e.hlx)<(g.playerx+16)? 24:296;
    }
  }
  g.keys.left = g.playerx+16>tx+2; g.keys.right = g.playerx+16<tx-2;
  g.keys.up = g.playery+16>ty+2; g.keys.down = g.playery+16<ty-2;
  g.frame();
  minE=Math.min(minE,g.energy);
  if(g.end_wave){ endFrame=f; break; }
}
console.log('endFrame', endFrame, 'minE', minE, 'finalE', g.energy, 'score', g.score, 'ships', g.enemies.length);
EOF
